import { test } from "node:test";
import assert from "node:assert/strict";
import { parseCsv, toMarkdownTable, csvToMarkdownTable } from "./convert.mjs";

test("parseCsv splits plain rows on commas", () => {
  assert.deepEqual(parseCsv("name,age\nAda,36\nGrace,85\n"), [
    ["name", "age"],
    ["Ada", "36"],
    ["Grace", "85"],
  ]);
});

test("parseCsv keeps commas inside quoted fields", () => {
  assert.deepEqual(parseCsv('city,country\n"Austin, TX",USA\n'), [
    ["city", "country"],
    ["Austin, TX", "USA"],
  ]);
});

test("parseCsv unescapes doubled quotes", () => {
  assert.deepEqual(parseCsv('quote\n"She said ""hi"""\n'), [["quote"], ['She said "hi"']]);
});

test("parseCsv drops a trailing blank line", () => {
  assert.deepEqual(parseCsv("a,b\n1,2\n"), [["a", "b"], ["1", "2"]]);
});

test("toMarkdownTable renders a header, separator, and body rows", () => {
  const table = toMarkdownTable([
    ["name", "role"],
    ["Ada", "Engineer"],
  ]);
  assert.equal(table, "| name | role |\n| --- | --- |\n| Ada | Engineer |");
});

test("toMarkdownTable escapes pipe characters in cells", () => {
  const table = toMarkdownTable([["expr"], ["a|b"]]);
  assert.equal(table, "| expr |\n| --- |\n| a\\|b |");
});

test("toMarkdownTable turns embedded newlines into <br>", () => {
  const table = toMarkdownTable([["note"], ["line1\nline2"]]);
  assert.equal(table, "| note |\n| --- |\n| line1<br>line2 |");
});

test("toMarkdownTable pads short rows out to the header width", () => {
  const table = toMarkdownTable([
    ["a", "b", "c"],
    ["1"],
  ]);
  assert.equal(table, "| a | b | c |\n| --- | --- | --- |\n| 1 |  |  |");
});

test("csvToMarkdownTable parses and renders in one step", () => {
  const table = csvToMarkdownTable("name,role\nAda,Engineer\nGrace,Admiral\n");
  assert.equal(
    table,
    "| name | role |\n| --- | --- |\n| Ada | Engineer |\n| Grace | Admiral |"
  );
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { parseCsv, rowsToMarkdownTable, csvToMarkdownTable } from "./convert.mjs";

test("parseCsv splits simple rows on commas and newlines", () => {
  const rows = parseCsv("name,age\nAda,36\nGrace,85\n");
  assert.deepEqual(rows, [
    ["name", "age"],
    ["Ada", "36"],
    ["Grace", "85"],
  ]);
});

test("parseCsv handles quoted fields with embedded commas and quotes", () => {
  const rows = parseCsv('name,quote\n"Lovelace, Ada","She said ""hello"""\n');
  assert.deepEqual(rows, [
    ["name", "quote"],
    ["Lovelace, Ada", 'She said "hello"'],
  ]);
});

test("parseCsv handles quoted fields with embedded newlines", () => {
  const rows = parseCsv('name,bio\nAda,"line one\nline two"\n');
  assert.deepEqual(rows, [
    ["name", "bio"],
    ["Ada", "line one\nline two"],
  ]);
});

test("parseCsv ignores a trailing blank line", () => {
  const rows = parseCsv("a,b\n1,2\n");
  assert.equal(rows.length, 2);
});

test("rowsToMarkdownTable renders a header separator and body rows", () => {
  const table = rowsToMarkdownTable([
    ["name", "age"],
    ["Ada", "36"],
  ]);
  assert.equal(
    table,
    "| name | age |\n| --- | --- |\n| Ada | 36 |\n"
  );
});

test("rowsToMarkdownTable pads short rows and truncates long ones to the header width", () => {
  const table = rowsToMarkdownTable([
    ["a", "b", "c"],
    ["1"],
    ["2", "3", "4", "5"],
  ]);
  assert.equal(
    table,
    "| a | b | c |\n| --- | --- | --- |\n| 1 |  |  |\n| 2 | 3 | 4 |\n"
  );
});

test("rowsToMarkdownTable escapes pipe characters and newlines in cells", () => {
  const table = rowsToMarkdownTable([
    ["col"],
    ["a | b"],
  ]);
  assert.match(table, /a \\\| b/);
});

test("rowsToMarkdownTable rejects zero rows", () => {
  assert.throws(() => rowsToMarkdownTable([]));
});

test("csvToMarkdownTable converts a simple csv end to end", () => {
  const table = csvToMarkdownTable("name,role\nAda,Mathematician\nGrace,Admiral\n");
  assert.equal(
    table,
    "| name | role |\n| --- | --- |\n| Ada | Mathematician |\n| Grace | Admiral |\n"
  );
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { parseCsv, csvToMarkdownTable } from "./convert.mjs";

test("parseCsv splits plain rows on commas and newlines", () => {
  const rows = parseCsv("name,age\nAda,36\nGrace,85\n");
  assert.deepEqual(rows, [
    ["name", "age"],
    ["Ada", "36"],
    ["Grace", "85"],
  ]);
});

test("parseCsv handles quoted fields with embedded commas and newlines", () => {
  const rows = parseCsv('name,bio\n"Lovelace, Ada","Wrote notes\non the engine"\n');
  assert.deepEqual(rows, [
    ["name", "bio"],
    ["Lovelace, Ada", "Wrote notes\non the engine"],
  ]);
});

test("parseCsv unescapes doubled quotes", () => {
  const rows = parseCsv('quote\n"She said ""hi"""\n');
  assert.deepEqual(rows, [["quote"], ['She said "hi"']]);
});

test("parseCsv tolerates a trailing newline-less last row", () => {
  const rows = parseCsv("a,b\n1,2");
  assert.deepEqual(rows, [
    ["a", "b"],
    ["1", "2"],
  ]);
});

test("csvToMarkdownTable renders a header, separator, and body rows", () => {
  const table = csvToMarkdownTable("name,age\nAda,36\nGrace,85\n");
  assert.equal(
    table,
    ["| name | age |", "| --- | --- |", "| Ada | 36 |", "| Grace | 85 |"].join("\n")
  );
});

test("csvToMarkdownTable escapes pipes and collapses newlines in cells", () => {
  const table = csvToMarkdownTable('a|b,note\n1,"line one\nline two"\n');
  assert.equal(
    table,
    ["| a\\|b | note |", "| --- | --- |", "| 1 | line one<br>line two |"].join("\n")
  );
});

test("csvToMarkdownTable pads short rows to the header's column count", () => {
  const table = csvToMarkdownTable("a,b,c\n1,2\n");
  assert.equal(table, ["| a | b | c |", "| --- | --- | --- |", "| 1 | 2 |  |"].join("\n"));
});

test("csvToMarkdownTable returns an empty string for empty input", () => {
  assert.equal(csvToMarkdownTable(""), "");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { csvToMarkdownTable } from "./convert.mjs";

test("converts a simple csv into a markdown table", () => {
  const csv = "name,role\nAda,Engineer\nGrace,Admiral\n";
  const expected = ["| name | role |", "| --- | --- |", "| Ada | Engineer |", "| Grace | Admiral |", ""].join(
    "\n",
  );
  assert.equal(csvToMarkdownTable(csv), expected);
});

test("handles a quoted field containing a comma", () => {
  const csv = 'name,address\nAda,"London, UK"\n';
  const expected = ["| name | address |", "| --- | --- |", "| Ada | London, UK |", ""].join("\n");
  assert.equal(csvToMarkdownTable(csv), expected);
});

test("unescapes doubled quotes inside a quoted field", () => {
  const csv = 'name,quote\nAda,"She said ""hello"""\n';
  const expected = ["| name | quote |", "| --- | --- |", '| Ada | She said "hello" |', ""].join("\n");
  assert.equal(csvToMarkdownTable(csv), expected);
});

test("escapes pipe characters in cell values", () => {
  const csv = "name,note\nAda,a|b\n";
  const expected = ["| name | note |", "| --- | --- |", "| Ada | a\\|b |", ""].join("\n");
  assert.equal(csvToMarkdownTable(csv), expected);
});

test("replaces newlines inside a quoted field with <br>", () => {
  const csv = 'name,bio\nAda,"Line one\nLine two"\n';
  const expected = ["| name | bio |", "| --- | --- |", "| Ada | Line one<br>Line two |", ""].join("\n");
  assert.equal(csvToMarkdownTable(csv), expected);
});

test("pads short rows out to the header's column count", () => {
  const csv = "a,b,c\n1,2\n";
  const expected = ["| a | b | c |", "| --- | --- | --- |", "| 1 | 2 |  |", ""].join("\n");
  assert.equal(csvToMarkdownTable(csv), expected);
});

test("works without a trailing newline on the last row", () => {
  const csv = "name,role\nAda,Engineer";
  const expected = ["| name | role |", "| --- | --- |", "| Ada | Engineer |", ""].join("\n");
  assert.equal(csvToMarkdownTable(csv), expected);
});

test("returns an empty string for empty input", () => {
  assert.equal(csvToMarkdownTable(""), "");
});
